function dir$dmkhupho(p){
  this.constructor(p);
}
dir$dmkhupho.prototype = new DirEvent();
dir$dmkhupho.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmkhupho.prototype.afterInit = function(renderType){
  var p = this._dir;

}

function dir$LoadMaKhuPhoMaPhuongXa(p){
	var maKhupho = p.valForm('ma_khupho'), maPhuongxa = p.valForm('ma_phuongxa');

	if(p.options.action == 'NEW') {	
		p.request('LoadMaKhuPhoMaPhuongXa', '', ['ma_phuongxa']);
	}
}

dir$dmkhupho.prototype.formFieldValueChange = function(o, cF, v) {
    var p = this._dir, maKhupho = p.valForm('ma_khupho');
	switch (cF){
		case 'ma_phuongxa':
			dir$LoadMaKhuPhoMaPhuongXa(p);
		break;

		default:
		  break;
	}
};

function dir$dmkhuphoDisabledMasterField(p){
	var maKhupho = p.valForm('ma_khupho');
	if (maKhupho !== '') {
		p.setDisabled('ma_khupho', true);
	}
	else {
		p.setDisabled('ma_khupho', false);
	}
}






